//! Excluded actual-gallery Chat message composition and host-action replay.
use dioxus::prelude::*;
use dioxus_ix::*;

#[path = "../../examples/gallery/chat.rs"]
mod gallery_chat;

#[component]
pub fn ChatMessagesPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_chat::STYLES} }
        style { {super::chat_composer_review::CHAT_COMPOSER_STYLES} }
        IxTheme { class:"chat-messages-review",
            gallery_chat::ChatExamples {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_CHAT_MESSAGES_CHECK);let _=query.send("chatmessages");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Chat messages: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Chat messages failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(60)).await;eprintln!("Chat messages native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
